                      'publication date, inclusive, until the next publication. AED is always 1.\n'
                      '"""\n'
                      '\n'
                      'import bisect\n'
                      'import csv\n'
                      'import datetime as dt\n'
                      'from decimal import Decimal\n'
                      'from functools import lru_cache\n'
                      'from pathlib import Path\n'
                      '\n'
                      'from ledger.money import D, round_money\n'
                      '\n'
                      'RATES = Path(__file__).parent / "data" / "fx_rates.csv"\n'
                      '\n'
                      '\n'
                      '@lru_cache(maxsize=1)\n'
                      'def _table() -> dict[str, list[tuple[dt.date, Decimal]]]:\n'
                      '    by_ccy: dict[str, list[tuple[dt.date, Decimal]]] = {}\n'
                      '    with RATES.open(newline="") as f:\n'
                      '        for row in csv.DictReader(f):\n'
                      '            by_ccy.setdefault(row["currency"], []).append(\n'
                      '                (dt.date.fromisoformat(row["published_on"]), '
                      'D(row["aed_per_unit"])))\n'
                      '    for rows in by_ccy.values():\n'
                      '        rows.sort()\n'
                      '    return by_ccy\n'
                      '\n'
                      '\n'
                      'def currencies() -> list[str]:\n'
                      '    return ["AED", *sorted(_table())]\n'
                      '\n'
                      '\n'
                      'def rate_on(currency: str, day: dt.date) -> Decimal:\n'
